"""Capture the fixed weight lookup for renderer lightmap weighting."""

# Locate shared tools from both the checkout and the browser's virtual filesystem.
import sys as _tool_sys
from pathlib import Path as _ToolPath
_tool_sys.path.insert(0, str(next(p for p in _ToolPath(__file__).resolve().parents
                                    if (p / 'lib/project.py').is_file())))
from lib.project import ROOT as _PROJECT_ROOT, tool_script as _tool_script

from pathlib import Path
import hashlib, json, base64, zlib
from PIL import Image
from lib.retail_paths import DLL

DEFAULT_WEIGHTS_ZLIB = b""

data = zlib.decompress(base64.b64decode(DEFAULT_WEIGHTS_ZLIB))

out = Path('assets/images/lightmap_weights.png')
out.parent.mkdir(parents=True, exist_ok=True)
Image.frombytes('RGBA', (32, 32), data, 'raw', 'BGRA').save(out)
evidence_path = Path('artifacts/retail-menu-evidence/renderer/weights.json')
evidence_path.parent.mkdir(parents=True, exist_ok=True)
p = DLL
dll_hash = hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else ''
evidence_path.write_text(json.dumps({'sha256': dll_hash, 'generator': '0x1000feb0', 'weights': '0x1000fd90', 'bytes_sha256': hashlib.sha256(data).hexdigest(), 'boundary': 'Image allocation and upload intercepted; generator executes original instructions.'}, indent=2))
print('Extracted native 32x32 lightmap weights')
